fiches.c:
$Source = "C:\data"
$Cible = "E:\backup\data"
$Log = "C:\logs\robocopy-data.log"
robocopy $Source $Cible /MIR /Z /R:3 /W:5 /LOG:$Log /NDL /NP
$Code = $LASTEXITCODE
if ($Code -lt 8) {
    Write-Host "Sauvegarde terminée, code $Code" -ForegroundColor Green
} else {
    Write-Warning "Sauvegarde échouée, code $Code"
}
exit $Code
